<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><nav class="breadcrumb"><a href="<?= url('/admin/dashboard') ?>">Dashboard</a><i data-lucide="chevron-right"></i><a href="<?= url('/admin/students') ?>">Students</a><i data-lucide="chevron-right"></i><span>Families</span></nav><h1>Manage Families</h1><p>Group siblings and related students under a shared family name.</p></div></header><form class="filter-bar filter-bar--compact" method="get"><div class="module-field"><label for="family-search">Search students</label><input class="module-input" id="family-search" name="search" value="<?= e($search) ?>" placeholder="Name or registration"></div><div></div><button class="btn btn--secondary">Search</button></form><form method="post" action="<?= url('/admin/students/families') ?>"><?= csrf_field() ?><section class="module-card"><header class="module-card__header"><div><h2>Family Assignments</h2><p>Use the same family name for students who belong together.</p></div></header><div class="module-card__body"><?php if(!$students):?><div class="compact-empty"><h3>No students found</h3></div><?php else:?><div class="table-scroll"><table class="data-table"><thead><tr><th>Student</th><th>Registration</th><th>Class</th><th>Family name</th></tr></thead><tbody><?php foreach($students as$s):?><tr><td><?= e($s['student_name']) ?></td><td><?= e($s['registration_no']) ?></td><td><?= e($s['class_name']) ?></td><td><input class="module-input" name="families[<?= e($s['id']) ?>]" value="<?= e($s['family']??'') ?>" maxlength="120" placeholder="Not grouped"></td></tr><?php endforeach?></tbody></table></div><?php endif?></div><?php if($students):?><footer class="module-card__footer"><button class="btn btn--primary" type="submit"><i data-lucide="save"></i>Save Families</button></footer><?php endif?></section></form></div></div></main>
